('c2-modal-nuances', 21, 'phrasal', 'turn up', 'gəlib çıxmaq', 'появляться', 'She may well [turn up] later.'),
('c2-modal-nuances', 22, 'phrasal', 'hang on', 'gözləmək', 'подождать', 'We might as well [hang on] a few more minutes.'),
('c2-modal-nuances', 23, 'phrasal', 'head off', 'yola düşmək', 'отправляться', 'It''s late, so we might as well [head off].'),
('c2-modal-nuances', 24, 'phrasal', 'do without', '...sız keçinmək', 'обходиться без', 'We could have [done without] the extra luggage.'),
('c2-modal-nuances', 25, 'phrasal', 'stay up', 'gec yatmaq', 'не ложиться спать', 'You needn''t have [stayed up] for me.'),
('c2-formal-linkers', 21, 'phrasal', 'sum up', 'yekunlaşdırmaq', 'подводить итог', 'To [sum up], the plan is too risky.'),
('c2-formal-linkers', 22, 'phrasal', 'set out', 'izah etmək, şərh etmək', 'излагать', 'The report [sets out] the main arguments.'),
('c2-formal-linkers', 23, 'phrasal', 'go along with', 'razılaşmaq', 'соглашаться с', 'I can''t [go along with] that decision.'),
('c2-formal-linkers', 24, 'phrasal', 'account for', 'izah etmək', 'объяснять', 'How do you [account for] the delay?'),
('c2-formal-linkers', 25, 'phrasal', 'spell out', 'aydın izah etmək', 'разъяснять', 'Let me [spell out] the consequences.')
) as v(slug, position, kind, term, az, ru, example)
join lessons l on l.slug = v.slug
where not exists (
  select 1 from lesson_vocab x where x.lesson_id = l.id and x.position = v.position
);

insert into practice_topics (slug, level, position, title, title_en, title_ru, questions) values
('c2-ai-future-work', 'C2', 1, 'Süni intellekt və işin gələcəyi', 'AI and the future of work', 'ИИ и будущее работы',
  array['To what extent will artificial intelligence change your profession in the next ten years?', 'Which jobs do you think are least likely to be replaced by machines, and why?', 'Should governments protect workers whose jobs disappear because of automation? How?', 'Is it ethical for companies to use AI to choose which candidates to hire?', 'How might education need to change to prepare people for an AI-driven economy?', 'Would you trust an AI to make medical decisions about your health? Why or why not?', 'Some say AI will create more jobs than it destroys. How convincing do you find this argument?', 'Who should be held responsible when an AI system makes a serious mistake?', 'How has technology already changed the way you work or study?', 'If you could ask an AI one question about the future, what would it be?']),
('c2-ethics-dilemmas', 'C2', 2, 'Etik dilemmalar', 'Ethical dilemmas', 'Этические дилеммы',
  array['Is it ever acceptable to lie? Give an example where you think it would be justified.', 'Would you report a close friend who had committed a minor crime? Why or why not?', 'Should doctors always tell patients the whole truth, even when it is devastating?', 'Is it fair to judge historical figures by today''s moral standards?', 'Where would you draw the line between privacy and public safety?', 'Is it morally wrong to buy cheap products made in poor working conditions?', 'Should rich countries have a duty to accept refugees? To what extent?', 'Can a good action be wrong if it is done for the wrong reasons?', 'Do you think morality is universal or does it depend on culture?', 'Describe a difficult moral choice you have had to make. Would you decide differently now?']),
('c2-globalisation', 'C2', 3, 'Qloballaşma', 'Globalisation', 'Глобализация',
  array['Has globalisation done more good than harm? Justify your opinion.', 'How has globalisation affected the culture and traditions of your country?', 'Are local businesses able to survive in a globalised economy? What helps them?', 'Is English becoming a threat to smaller languages?', 'Should countries try to produce everything they need themselves? Why or why not?', 'How does globalisation affect inequality within and between countries?', 'Do you consider yourself a global citizen? What does that mean to you?', 'What role should international organisations play in solving global problems?', 'Has the pandemic changed people''s attitude towards globalisation?', 'What do you think the world economy will look like in fifty years?']),
('c2-media-truth', 'C2', 4, 'Media və həqiqət', 'The media and the truth', 'СМИ и правда',
  array['How do you decide whether a news story is reliable?', 'Is there such a thing as completely objective journalism?', 'Should social media companies be responsible for the content their users post?', 'How dangerous do you consider "fake news" to democracy?', 'Should journalists ever be allowed to break the law to uncover the truth?', 'Has the internet made people better or worse informed?', 'Is it acceptable for the media to report on the private lives of public figures?', 'How can schools teach young people to think critically about the media?', 'Do you think traditional newspapers will survive? Why or why not?', 'Which source of information do you trust most, and why?']),
('c2-success-happiness', 'C2', 5, 'Uğur və xoşbəxtlik', 'Success and happiness', 'Успех и счастье',
  array['How would you define success? Has your definition changed over the years?', 'Is it possible to be successful without being happy, or happy without being successful?', 'To what extent is success determined by luck rather than hard work?', 'Does money buy happiness? Where does its influence stop?', 'Why do some very successful people feel unfulfilled?', 'Should schools teach children how to be happy? What would that look like?', 'How do different cultures view success?', 'What is the greatest obstacle to happiness in modern life?', 'Can failure be more valuable than success? Give an example.', 'Describe someone you consider truly successful. Why do you admire them?']),
('c2-education-systems', 'C2', 6, 'Təhsil sistemləri', 'Education systems', 'Системы образования',
  array['What are the main strengths and weaknesses of the education system in your country?', 'Should university education be free for everyone?', 'Are exams a fair way to measure ability and knowledge?', 'How important is it for students to learn creativity rather than facts?', 'Should children be allowed to choose what subjects they study from an early age?', 'Will online learning ever fully replace traditional classrooms?', 'What qualities make an outstanding teacher?', 'Is it better to specialise early or to have a broad education?', 'How should schools deal with students who are much more able than their classmates?', 'If you could change one thing about the way you were educated, what would it be?']),
('c2-climate-responsibility', 'C2', 7, 'İqlim və məsuliyyət', 'Climate and responsibility', 'Климат и ответственность',
  array['Who bears the greatest responsibility for tackling climate change: individuals, companies or governments?', 'Are personal efforts such as recycling meaningful, or merely symbolic?', 'Should flying be made more expensive to reduce emissions?', 'How should poorer countries balance economic growth with environmental protection?', 'Is technology likely to save us from the climate crisis?', 'How has climate change already affected your region?', 'Should eating meat be discouraged for environmental reasons?', 'Is protest an effective way to bring about environmental change?', 'What sacrifices are you personally willing to make for the environment?', 'How optimistic are you about the planet''s future? Why?']),
('c2-art-value', 'C2', 8, 'İncəsənətin dəyəri', 'The value of art', 'Ценность искусства',
  array['What is the purpose of art in society?', 'Should governments fund the arts, even in times of economic difficulty?', 'Can art created by AI be considered real art?', 'Why do some artworks sell for millions? Is that justified?', 'Is good art always beautiful?', 'Should offensive or controversial art be censored?', 'Which art form do you find most powerful, and why?', 'How does art reflect the time in which it was created?', 'Is street art vandalism or a legitimate art form?', 'Describe a work of art that has had a deep effect on you.']),
('c2-leadership', 'C2', 9, 'Liderlik', 'Leadership', 'Лидерство',
  array['Are leaders born or made?', 'What distinguishes a good manager from a great leader?', 'Is it more important for a leader to be liked or to be respected?', 'Should leaders always be honest with the people they lead?', 'How has the idea of leadership changed in the last few decades?', 'Can someone be an effective leader without any formal authority?', 'What leadership qualities are most needed in a crisis?', 'Should there be age limits for political leaders?', 'Describe a leader you admire. What makes them effective?', 'Have you ever had to lead a group? What did you learn from it?']),
('c2-cities-future', 'C2', 10, 'Gələcəyin şəhərləri', 'Cities of the future', 'Города будущего',
  array['What will the ideal city of the future look like?', 'Should cars be banned from city centres?', 'How can cities provide affordable housing for young people?', 'Is the move from the countryside to cities inevitable?', 'How can architecture influence people''s wellbeing?', 'Should historic buildings be preserved at all costs?', 'What are the advantages and disadvantages of "smart cities" that collect data on residents?', 'How can cities become more inclusive for elderly and disabled people?', 'Would you prefer to live in a megacity or a small town? Why?', 'What one change would most improve the city you live in?']),
('c2-language-identity', 'C2', 11, 'Dil və kimlik', 'Language and identity', 'Язык и идентичность',
  array['To what extent does the language we speak shape the way we think?', 'Do you feel like a different person when you speak another language?', 'Should countries have one official language or several?', 'What is lost when a language dies?', 'Is it important to speak a foreign language without an accent?', 'How has your native language changed in your lifetime?', 'Should children be raised bilingual whenever possible?', 'Does slang enrich or damage a language?', 'Why do some languages become global while others do not?', 'What does your native language allow you to express that English does not?']),
('c2-health-society', 'C2', 12, 'Sağlamlıq və cəmiyyət', 'Health and society', 'Здоровье и общество',
  array['Should healthy lifestyles be encouraged by taxes, for example on sugar?', 'Is mental health given enough attention in your country?', 'Who should pay for healthcare: individuals or the state?', 'How has modern technology affected people''s health?', 'Should vaccinations be compulsory?', 'Is the pressure to look perfect harmful to public health?', 'How important is work-life balance for health?', 'Should people who lead unhealthy lifestyles pay more for healthcare?', 'What could be done to help people live longer, healthier lives?', 'What do you personally do to stay physically and mentally healthy?']),
('c2-science-limits', 'C2', 13, 'Elmin sərhədləri', 'The limits of science', 'Границы науки',
  array['Should there be limits on scientific research? Who should set them?', 'Is genetic engineering of humans ever acceptable?', 'Is space exploration worth the enormous cost?', 'Can science answer every question, or are some questions beyond its reach?', 'Why do some people distrust scientists?', 'Should animals be used in medical research?', 'Which scientific discovery do you think has changed the world the most?', 'How should governments respond when scientists disagree?', 'Do the benefits of nuclear energy outweigh the risks?', 'If you could fund one area of research, what would it be and why?']),
('c2-generations', 'C2', 14, 'Nəsillər arası fərq', 'Generations', 'Поколения',
  array['What are the main differences between your generation and your parents''?', 'Is the "generation gap" bigger today than in the past?', 'What can older people learn from younger people, and vice versa?', 'Are young people today more or less ambitious than previous generations?', 'Should older people be encouraged to keep working?', 'How has the role of grandparents changed?', 'Is it fair to blame previous generations for today''s problems?', 'How do different generations use technology differently?', 'What values would you most like to pass on to the next generation?', 'Describe a conversation with an older relative that changed your view of something.']),
('c2-travel-tourism', 'C2', 15, 'Turizm və onun təsiri', 'Tourism and its impact', 'Туризм и его влияние',
  array['Does mass tourism do more harm than good to popular destinations?', 'Should there be limits on the number of tourists visiting certain places?', 'What is the difference between a traveller and a tourist?', 'How can tourism benefit local communities rather than large companies?', 'Has social media changed the way people travel?', 'Is it responsible to travel abroad frequently, considering the environmental impact?', 'What makes a travel experience truly memorable?', 'How should your country present itself to tourists?', 'Is it possible to understand a culture as a short-term visitor?', 'Describe a journey that changed your perspective.']),
('c2-law-justice', 'C2', 16, 'Qanun və ədalət', 'Law and justice', 'Закон и справедливость',
  array['Is the purpose of prison to punish or to rehabilitate?', 'Are laws and justice always the same thing?', 'Should the death penalty exist anywhere in the world?', 'Is it ever right to break an unjust law?', 'Should famous people receive the same treatment in court as everyone else?', 'How can societies reduce crime among young people?', 'Should jury trials be replaced by professional judges?', 'How should the law deal with crimes committed online?', 'Is it fair that rich people can afford better lawyers?', 'What law would you introduce if you had the power, and why?']),
('c2-consumerism', 'C2', 17, 'İstehlak cəmiyyəti', 'Consumerism', 'Общество потребления',
  array['Do we buy too many things we don''t need? Why?', 'How does advertising influence our sense of identity?', 'Is the minimalist lifestyle a solution or just another trend?', 'Should products be designed to last longer by law?', 'Has online shopping changed people''s habits for better or worse?', 'Is "retail therapy" a real way to feel better?', 'Should children be protected from advertising?', 'How do brands create loyalty among customers?', 'Can economic growth continue without increased consumption?', 'What is the best thing you have ever bought, and why?']),
('c2-privacy-digital', 'C2', 18, 'Rəqəmsal dövrdə məxfilik', 'Privacy in the digital age', 'Конфиденциальность в цифровую эпоху',
  array['Is privacy still possible in the digital age?', 'Would you give up some privacy for more convenience? Where is your limit?', 'Should employers be allowed to monitor their staff''s online activity?', 'Do people share too much about themselves on social media?', 'Should children have a right to privacy from their parents online?', 'How should personal data be protected by law?', 'Is facial recognition in public places acceptable?', 'Should we have the right to have information about us deleted from the internet?', 'How has technology changed our idea of friendship?', 'What steps do you take to protect your privacy online?']),
('c2-work-life', 'C2', 19, 'İş və həyat balansı', 'Work and life balance', 'Баланс работы и жизни',
  array['Is a four-day working week a realistic idea?', 'Has remote working improved or damaged work-life balance?', 'Should people choose a career for passion or for money?', 'Is it healthy to define yourself by your job?', 'How important is job security compared with job satisfaction?', 'Should companies be responsible for their employees'' wellbeing?', 'Is ambition always a positive quality?', 'How will the idea of a "career" change in the future?', 'What would make your working or studying life more balanced?', 'Describe your ideal working day.']),
('c2-humour-culture', 'C2', 20, 'Yumor və mədəniyyət', 'Humour and culture', 'Юмор и культура',
  array['Does humour translate well between cultures? Give examples.', 'Are there topics that should never be joked about?', 'Why is humour so important in human relationships?', 'What does a country''s humour tell you about its people?', 'Is sarcasm a sign of intelligence or of unkindness?', 'How has humour changed with the internet and memes?', 'Can humour be used effectively in serious situations, such as business or politics?', 'Who is the funniest person you know, and what makes them funny?', 'Is it harder to be funny in a foreign language? Why?', 'Tell a story about a time when a joke was misunderstood.'])
on conflict (slug) do nothing;

insert into test_questions (position, question, options, correct)
select v.position, v.question, v.options, v.correct
from (values
(21, '___ it not for your help, I would have given up.', array['Were', 'Had', 'Should', 'Did'], 0),
(22, 'Much ___ I admire her work, I can''t support this idea.', array['as', 'though', 'so', 'that'], 0),
(23, 'You ___ have cooked; we had already eaten.', array['needn''t', 'mustn''t', 'couldn''t', 'didn''t need'], 0),
(24, 'The ancient bridge is believed ___ by the Romans.', array['to have been built', 'to build', 'being built', 'to have built'], 0)
) as v(position, question, options, correct)
where not exists (select 1 from test_questions x where x.question = v.question);

insert into level_teachers (level, name, intro, intro_az, intro_ru) values (
  'C2',
  'Edward',
  'Hello, and welcome to C2, the highest level. I''m Edward, your video teacher.

In six short lessons, we polish the details that make English truly precise: formal inversion, hedging, advanced passives, concession, modal nuances and formal linkers.

Each lesson has a short video, tests and new words. Enjoy the finer points of English. Let''s begin!',
  'Salam! Mən Edward, C2 səviyyəsi üzrə video müəlliminizəm. Altı qısa dərsdə ingilis dilini tam dəqiq edən incəlikləri keçəcəyik: rəsmi inversiya, hedging, mürəkkəb passiv, güzəşt, modal fellərin incəlikləri və rəsmi bağlayıcılar.',
  'Здравствуйте! Я Эдвард, ваш видеопреподаватель уровня C2. За шесть коротких уроков мы отточим детали, которые делают английский по-настоящему точным: инверсию, хеджирование, сложный пассив, уступку, нюансы модальных глаголов и формальные связки.'
) on conflict (level) do nothing;

notify pgrst, 'reload schema';
